#!/usr/bin/env python3
"""HarborPass JSON command-line application."""
import json
import sys
from datetime import date, timedelta


def notice(account):
    plan_cents = account["plan_cents"]
    credit_cents = 0
    if account["autopay"] and account["completed_years"] >= 2:
        credit_cents = min(plan_cents // 10, 2400)
    send_on = date.fromisoformat(account["renewal_on"]) - timedelta(days=21)
    return {
        "customer_id": account["customer_id"],
        "send_on": send_on.isoformat(),
        "credit_cents": credit_cents,
        "amount_due_cents": plan_cents - credit_cents,
    }


def csv_field(value):
    text = str(value)
    if any(character in text for character in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def export_notices(accounts):
    columns = ("customer_id", "send_on", "credit_cents", "amount_due_cents")
    rows = [",".join(columns)]
    for account in accounts:
        account_notice = notice(account)
        rows.append(",".join(csv_field(account_notice[column]) for column in columns))
    return {"csv": "\n".join(rows) + "\n", "count": len(accounts)}


def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "HarborPass"}
    if request.get("command") == "notice":
        return notice(request["account"])
    if request.get("command") == "export":
        return export_notices(request["accounts"])
    return {"error": "unknown_command"}


def main():
    request = json.load(sys.stdin)
    response = handle(request)
    json.dump(response, sys.stdout)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
# HarborPass renewal CLI

HarborPass sells annual memberships. This project is a small local JSON application. It requires Python 3.9 or later and no packages or network access.

Run `python3 main.py` with one JSON request on standard input. The program writes one JSON response to standard output. Currently `{"command":"ping"}` returns `{"status":"ok","product":"HarborPass"}`; an unrecognized command returns `{"error":"unknown_command"}`. JSON key order and surrounding JSON whitespace do not matter.

Use `{"command":"notice","account":ACCOUNT}` to generate a renewal notice. Release 1.0 sends notices 21 calendar days before renewal. Members with autopay enabled and at least 2 completed years receive a 10% loyalty credit, rounded down to whole cents and capped at 2400 cents. Other members receive no credit. The amount due is the plan price minus the credit.

Use `{"command":"export","accounts":[ACCOUNT,...]}` to export the current notices as `{"csv":STRING,"count":N}`. The CSV columns are `customer_id,send_on,credit_cents,amount_due_cents`, with a header and LF after every row, including the last. Fields containing commas, double quotes, CR, or LF are quoted, with internal quotes doubled. Input order and duplicate IDs are preserved; an empty collection returns just the header and its LF with count 0.

Run the starter tests with `python3 -m unittest discover -s tests -v`. Each product issue is accompanied by a public JSON examples file. Run those examples with `python3 test_public.py --cases /path/to/stage_N.json`. Feature examples for an earlier stage can become obsolete when a later issue explicitly changes its business requirements; the issue history remains available to explain prior releases.

Accounts use customer_id (nonempty string), renewal_on (valid Gregorian YYYY-MM-DD from 2020-01-01 through 2099-12-31), plan_cents (nonnegative integer US cents), completed_years (nonnegative integer), and autopay (boolean). A notice contains customer_id, send_on, credit_cents, and amount_due_cents. Account collections preserve order and duplicate customer IDs. Inputs to the exercises are well formed. No current clock, locale, or remote data is needed.

Implement product issues in their supplied order. Source code, docs, tests, and prior issue text remain available throughout the sequence.

import json
from pathlib import Path
import subprocess
import sys
import unittest

ROOT = Path(__file__).resolve().parents[1]


class SmokeTests(unittest.TestCase):
    def call(self, request):
        result = subprocess.run([sys.executable, str(ROOT / "main.py")], input=json.dumps(request), capture_output=True, text=True, check=True, timeout=3)
        return json.loads(result.stdout)

    def test_ping(self):
        self.assertEqual(self.call({"command": "ping"}), {"status": "ok", "product": "HarborPass"})

    def test_unknown_command(self):
        self.assertEqual(self.call({"command": "not_a_command"}), {"error": "unknown_command"})

    def test_notice_credit(self):
        cases = [
            (19999, 2, True, 1999),
            (19999, 2, False, 0),
            (19999, 1, True, 0),
            (19999, 0, False, 0),
            (90000, 8, True, 2400),
            (23999, 2, True, 2399),
            (24000, 2, True, 2400),
            (24010, 2, True, 2400),
            (0, 2, True, 0),
            (9, 2, True, 0),
        ]
        for plan, years, autopay, credit in cases:
            with self.subTest(plan=plan, years=years, autopay=autopay):
                account = {
                    "customer_id": "M-17",
                    "renewal_on": "2026-04-15",
                    "plan_cents": plan,
                    "completed_years": years,
                    "autopay": autopay,
                }
                self.assertEqual(self.call({"command": "notice", "account": account}), {
                    "customer_id": "M-17",
                    "send_on": "2026-03-25",
                    "credit_cents": credit,
                    "amount_due_cents": plan - credit,
                })

    def test_export_empty(self):
        self.assertEqual(self.call({"command": "export", "accounts": []}), {
            "csv": "customer_id,send_on,credit_cents,amount_due_cents\n",
            "count": 0,
        })

    def test_export_csv_quoting(self):
        cases = [
            ("M-17", "M-17"),
            ("comma,id", '"comma,id"'),
            ('quote"id', '"quote""id"'),
            ("cr\rid", '"cr\rid"'),
            ("lf\nid", '"lf\nid"'),
            ('all,\r\n"id', '"all,\r\n""id"'),
            (" space\t雪 ", " space\t雪 "),
        ]
        accounts = [{
            "customer_id": customer_id,
            "renewal_on": "2026-04-15",
            "plan_cents": 19999,
            "completed_years": 2,
            "autopay": True,
        } for customer_id, _ in cases]
        self.assertEqual(self.call({"command": "export", "accounts": accounts}), {
            "csv": "customer_id,send_on,credit_cents,amount_due_cents\n" + "".join(
                encoded + ",2026-03-25,1999,18000\n" for _, encoded in cases
            ),
            "count": len(cases),
        })

    def test_export_preserves_rows_and_notice_values(self):
        accounts = [
            {"customer_id": "repeat", "renewal_on": "2020-01-01",
             "plan_cents": 90000, "completed_years": 8, "autopay": True},
            {"customer_id": "other", "renewal_on": "2024-03-21",
             "plan_cents": 0, "completed_years": 0, "autopay": False},
            {"customer_id": "repeat", "renewal_on": "2099-12-31",
             "plan_cents": 9, "completed_years": 1, "autopay": True},
        ]
        accounts.append(accounts[0].copy())
        self.assertEqual(self.call({"command": "export", "accounts": accounts}), {
            "csv": "customer_id,send_on,credit_cents,amount_due_cents\n"
                   "repeat,2019-12-11,2400,87600\n"
                   "other,2024-02-29,0,0\n"
                   "repeat,2099-12-10,0,9\n"
                   "repeat,2019-12-11,2400,87600\n",
            "count": 4,
        })

    def test_notice_calendar_boundaries(self):
        cases = [
            ("2020-01-01", "2019-12-11"),
            ("2024-02-29", "2024-02-08"),
            ("2024-03-21", "2024-02-29"),
            ("2025-03-21", "2025-02-28"),
            ("2099-12-31", "2099-12-10"),
        ]
        for renewal_on, send_on in cases:
            with self.subTest(renewal_on=renewal_on):
                account = {
                    "customer_id": "calendar-member",
                    "renewal_on": renewal_on,
                    "plan_cents": 100,
                    "completed_years": 2,
                    "autopay": True,
                }
                self.assertEqual(self.call({"command": "notice", "account": account}), {
                    "customer_id": "calendar-member",
                    "send_on": send_on,
                    "credit_cents": 10,
                    "amount_due_cents": 90,
                })


if __name__ == "__main__":
    unittest.main()
"""Run an issue's externally supplied public examples against main.py."""
import argparse
import json
from pathlib import Path
import subprocess
import sys


def run():
    parser = argparse.ArgumentParser()
    parser.add_argument("--cases", type=Path, required=True)
    args = parser.parse_args()
    cases = json.loads(args.cases.read_text())
    failures = 0
    for case in cases:
        result = subprocess.run([sys.executable, str(Path(__file__).with_name("main.py"))], input=json.dumps(case["request"]), text=True, capture_output=True, timeout=3)
        try:
            actual = json.loads(result.stdout)
            success = result.returncode == 0 and actual == case["expected"]
        except ValueError:
            actual = result.stdout
            success = False
        print(("PASS " if success else "FAIL ") + case["name"])
        if not success:
            failures += 1
            print("  expected:", case["expected"])
            print("  actual:", actual)
            if result.stderr:
                print("  stderr:", result.stderr)
    return int(failures != 0)


if __name__ == "__main__":
    raise SystemExit(run())
